def find_shortest_cycle(n, files, dependencies):
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    for i in range(n):
        file_name = files[i]
        k = dependencies[i][1]
        for j in range(k):
            imported_file = dependencies[i][2 + j].strip()
            graph[file_name].append(imported_file)
            reverse_graph[imported_file].append(file_name)

    index = 0
    indices = {}
    lowlinks = {}
    stack = []
    on_stack = set()
    sccs = []

    def strongconnect(node):
        nonlocal index
        indices[node] = index
        lowlinks[node] = index
        index += 1
        stack.append(node)
        on_stack.add(node)

        for neighbor in graph[node]:
            if neighbor not in indices:
                strongconnect(neighbor)
                lowlinks[node] = min(lowlinks[node], lowlinks[neighbor])
            elif neighbor in on_stack:
                lowlinks[node] = min(lowlinks[node], indices[neighbor])

        if lowlinks[node] == indices[node]:
            scc = []
            while True:
                w = stack.pop()
                on_stack.remove(w)
                scc.append(w)
                if w == node:
                    break
            sccs.append(scc)

    for node in files:
        if node not in indices:
            strongconnect(node)

    shortest_cycle = None
    for scc in sccs:
        if len(scc) > 1:
            if shortest_cycle is None or len(scc) < len(shortest_cycle):
                shortest_cycle = scc

    if shortest_cycle:
        return ' '.join(shortest_cycle)
    else:
        return "SHIP IT"

